import {freshStartingDraft,applyStartingChoices,currentStartingChoice,startingDraftDescription,startingRefusal} from './starting-flow-core.mjs';
import {parisLengths,frenchLengths} from './reading-amounts.mjs';
import {hearButton,stopSpeech,bindSpeech} from './play-media.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const startingPages=[
 {id:'math',label:'Math',title:'What numbers shall we start with?',purpose:'These choices are for new Café orders. Other math places keep their own choices.',options:[['keep','Keep my Café choice','Use the existing Café choice.'],['small','Smaller orders','2–4 guests; 2–3 bites each.'],['all','All multiplication facts','1–12 guests and bites.']]},
 {id:'reading',label:'Reading',title:'How much English text today?',purpose:'For new Paris and Library reading visits.',options:[['keep','Keep my starting choice',''],['auto','Use suggestions','Let recent reading visits suggest an amount.'],...[1,2,3].map(n=>[n,parisLengths[n],''])]},
 {id:'french',label:'French',title:'How much French today?',purpose:'French can start somewhere different from English and math.',options:[['keep','Keep my starting choice',''],['auto','Use suggestions','Let recent French visits suggest an amount.'],...[1,2,3].map(n=>[n,frenchLengths[n],''])]},
 {id:'begin',label:'Begin',title:'Choose your first errand',purpose:'These choices are for future orders and new reading visits. Anything waiting keeps its own numbers and pages.'}
];
const destinations=[['#desk','Open the Keeper’s Desk','Sit with a longer question from the town.'],['#cafe','Go to the Café','Feed a waiting neighbor.'],['#paris','Read in Paris','Follow a story and a clue.'],['#french','Explore Paris in French','Read a little French together.'],['#explore','Choose another place','Keep every destination open.']];
let visit=null;
export function resetStartingFlow(){visit=null;}
export const startingInvitation=()=>'<aside class="starting-invitation"><a class="secondary" href="#begin">Find a place to begin</a><p>Choose numbers and reading amounts, or explore as you are.</p></aside>';
export const startingNotesLink=()=>'<section class="panel"><a class="secondary" href="#begin">Change starting choices</a><p>Choose Café and reading amounts for this explorer. The Café panel’s Sprout/Seedling/Sapling choices use the same small/full ranges.</p></section>';
const mark='<span aria-hidden="true"> ✓</span>';
function summary(v){return `<aside class="starting-summary"><h2>Your choices</h2>${['math','reading','french'].map(k=>`<p><strong>${{math:'Café math',reading:'English reading',french:'French'}[k]}</strong><br>${esc(startingDraftDescription(v.draft,k))}</p>`).join('')}</aside>`;}
export function startingNarration(v){
 const p=startingPages[v.page];
 return [p.title,p.purpose,...(p.options?['Current choice: '+currentStartingChoice(v.notebook,p.id),...p.options.flatMap(([value,label,detail])=>[label,detail,value===v.draft[p.id]?'Selected.':''])]:[...destinations.flatMap(([,label,purpose])=>[label,purpose]),...['math','reading','french'].map(k=>startingDraftDescription(v.draft,k))]),p.options?'Next: '+startingPages[v.page+1].label:'Choose a destination to apply these choices.', 'Skip and go Home.'].filter(Boolean).join(' ');
}
function body(v){const p=startingPages[v.page];return `<nav aria-label="Starting choices steps">${startingPages.map((x,i)=>`<button type="button" data-start-page="${i}"${i===v.page?' aria-current="step"':''}>${x.label}${i===v.page?mark:''}</button>`).join('')}</nav><h1 id="starting-title" tabindex="-1">${p.title}</h1><p>${p.purpose}</p>${p.options?`<p class="starting-current">Current choice: ${esc(currentStartingChoice(v.notebook,p.id))}</p><section class="starting-options" role="group" aria-label="Choose a starting amount">${p.options.map(([value,label,detail])=>`<button type="button" data-start-choice="${value}" aria-pressed="${value===v.draft[p.id]}"><span data-choice-label>${label}</span><span data-choice-mark aria-hidden="true">${value===v.draft[p.id]?' ✓':''}</span>${detail?`<span class="starting-detail">${detail}</span>`:''}</button>`).join('')}</section><p>You can choose a different amount inside each activity.</p>`:`<div class="starting-layout"><section class="starting-destinations" aria-label="First destination">${destinations.map(([hash,label,purpose])=>`<button type="button" data-start-go="${hash}">${label}<span class="starting-detail">${purpose}</span></button>`).join('')}</section>${summary(v)}</div><p>Choices are separate for this explorer. No level is assigned.</p>`}<div class="starting-actions">${v.page?`<button type="button" data-start-page="${v.page-1}">Back: ${startingPages[v.page-1].label}</button>`:''}${v.page<3?`<button type="button" data-start-page="${v.page+1}">Next: ${startingPages[v.page+1].label}</button>`:''}${hearButton('Current starting choices.','Hear this page')}<button type="button" data-start-go="#home" data-start-skip>Skip and go Home</button></div>`;}
export function startingFlowPage(notebook,owner){
 const fresh=!visit||visit.notebook!==notebook||visit.owner!==owner;
 if(fresh)visit={notebook,owner,draft:freshStartingDraft(),page:0,message:''};
 if(fresh&&typeof document!=='undefined'){const captured=visit;queueMicrotask(()=>{if(visit===captured&&location.hash==='#begin')document.querySelector('#starting-title')?.focus();});}
 return `<section class="starting-page" data-start-root><header><p>How shall we begin?</p><svg aria-hidden="true" viewBox="0 0 40 35"><path d="M20 32V12Q3-3 2 10Q3 23 20 22Q38 22 38 7Q24 5 20 16"/></svg></header><div data-start-view>${body(visit)}</div><p id="starting-status" role="status" aria-live="polite" tabindex="-1">${esc(visit.message)}</p><a href="#notes">Grown-up notes</a></section>`;
}
export function bindStartingFlow({notebook,explorerId,isActive,save,navigate,focus,canExport}){
 const root=document.querySelector('[data-start-root]');if(!root||!visit)return;const captured=visit,page=visit.page;
 const live=b=>b.isConnected&&root.isConnected&&root.contains(b)&&document.querySelector('[data-start-root]')===root&&visit===captured&&visit.page===page&&notebook()===captured.notebook&&explorerId()===captured.owner&&isActive()&&location.hash==='#begin';
 const options={notebook,explorerId,isActive,save,navigate,focus,canExport};
 root.querySelectorAll('[data-start-page]').forEach(b=>b.onclick=()=>{if(!live(b))return;stopSpeech();visit.page=Number(b.dataset.startPage);root.querySelector('[data-start-view]').innerHTML=body(visit);bindStartingFlow(options);bindSpeech();focus('#starting-title');});
 root.querySelectorAll('[data-start-choice]').forEach(b=>b.onclick=()=>{if(!live(b))return;stopSpeech();const value=b.dataset.startChoice;visit.draft[startingPages[page].id]=/^[123]$/.test(value)?Number(value):value;root.querySelectorAll('[data-start-choice]').forEach(x=>{const selected=x===b;x.setAttribute('aria-pressed',String(selected));x.querySelector('[data-choice-mark]').textContent=selected?' ✓':'';});});
 root.querySelectorAll('[data-start-go]').forEach(b=>b.onclick=()=>{if(!live(b))return;stopSpeech();if(!b.hasAttribute('data-start-skip')){const result=applyStartingChoices(captured.notebook,visit.draft,canExport);if(!result.ok){visit.message=startingRefusal;root.querySelector('#starting-status').textContent=visit.message;focus('#starting-status');return;}if(result.changed)save();visit.message='Choices ready for this explorer';root.querySelector('#starting-status').textContent=visit.message;}navigate(b.dataset.startGo);});
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=startingNarration(visit);},{capture:true}));
}
